def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                                fields.append(''.join(field))
                                break
                            else:
                                # Invalid: quote not followed by comma or end
                                return None
                        else:
                            fields.append(''.join(field))
                            break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains quote
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < len(line):
                # Skip the comma
                i += 1

    return fields

